package com.eitjank.chatscrollbarhider;

import lombok.RequiredArgsConstructor;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.Range;
import net.runelite.client.config.Units;

@ConfigGroup(ChatScrollbarHiderConfig.GROUP)
public interface ChatScrollbarHiderConfig extends Config
{
	String GROUP = "chatscrollbarhider";

	@RequiredArgsConstructor
	enum Mode
	{
		ALWAYS("Always"),
		IN_COMBAT("Only in combat");

		private final String name;

		@Override
		public String toString()
		{
			return name;
		}
	}

	@ConfigItem(
		keyName = "mode",
		name = "Mode",
		description = "When to hide the chatbox scrollbar. 'Only in combat' means you or your target"
			+ " took a hitsplat within the combat timeout.",
		position = 0
	)
	default Mode mode()
	{
		return Mode.ALWAYS;
	}

	@Range(min = 1, max = 300)
	@Units(Units.SECONDS)
	@ConfigItem(
		keyName = "combatTimeout",
		name = "Combat timeout",
		description = "In 'Only in combat' mode, how long after the last hitsplat the scrollbar stays hidden.",
		position = 1
	)
	default int combatTimeout()
	{
		return 15;
	}
}

package com.eitjank.chatscrollbarhider;

import com.google.inject.Provides;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Actor;
import net.runelite.api.Client;
import net.runelite.api.Player;
import net.runelite.api.ScriptID;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.HitsplatApplied;
import net.runelite.api.events.ScriptPostFired;
import net.runelite.api.events.WidgetLoaded;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;

@Slf4j
@PluginDescriptor(
	name = "Chat Scrollbar Hider",
	description = "Hides the chatbox scrollbar so clicks there reach the game world",
	tags = {"chat", "chatbox", "scrollbar", "misclick", "transparent", "bossing"}
)
public class ChatScrollbarHiderPlugin extends Plugin
{
	static final int NO_HITSPLAT = -1;
	private static final int GAME_TICK_MILLIS = 600;

	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private ChatScrollbarHiderConfig config;

	private int lastHitsplatTick = NO_HITSPLAT;
	// Only ever un-hide a scrollbar this plugin hid itself
	private boolean hiddenByPlugin;

	@Override
	protected void startUp()
	{
		lastHitsplatTick = NO_HITSPLAT;
		clientThread.invoke(this::refresh);
	}

	@Override
	protected void shutDown()
	{
		clientThread.invoke(() -> setScrollbarHidden(false));
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		refresh();
	}

	@Subscribe
	public void onHitsplatApplied(HitsplatApplied event)
	{
		Player local = client.getLocalPlayer();
		if (local == null)
		{
			return;
		}

		Actor actor = event.getActor();
		if (actor == local || actor == local.getInteracting())
		{
			lastHitsplatTick = client.getTickCount();
		}
	}

	@Subscribe
	public void onWidgetLoaded(WidgetLoaded event)
	{
		if (event.getGroupId() == InterfaceID.CHATBOX)
		{
			// A freshly loaded chatbox has a new, visible scrollbar widget
			hiddenByPlugin = false;
			refresh();
		}
	}

	@Subscribe
	public void onScriptPostFired(ScriptPostFired event)
	{
		if (event.getScriptId() == ScriptID.BUILD_CHATBOX)
		{
			refresh();
		}
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (ChatScrollbarHiderConfig.GROUP.equals(event.getGroup()))
		{
			clientThread.invoke(this::refresh);
		}
	}

	private void refresh()
	{
		setScrollbarHidden(shouldHide());
	}

	private boolean shouldHide()
	{
		// In fixed mode the chatbox sits below the viewport, so there is no game world to click through to
		if (!client.isResized())
		{
			return false;
		}

		if (config.mode() == ChatScrollbarHiderConfig.Mode.ALWAYS)
		{
			return true;
		}

		return isInCombat(lastHitsplatTick, client.getTickCount(), secondsToTicks(config.combatTimeout()));
	}

	private void setScrollbarHidden(boolean hide)
	{
		if (!hide && !hiddenByPlugin)
		{
			return;
		}

		Widget scrollbar = client.getWidget(InterfaceID.Chatbox.CHATSCROLLBAR);
		if (scrollbar == null)
		{
			return;
		}

		if (hide && !scrollbar.isSelfHidden())
		{
			log.debug("Hiding chatbox scrollbar");
			scrollbar.setHidden(true);
			hiddenByPlugin = true;
		}
		else if (!hide)
		{
			log.debug("Restoring chatbox scrollbar");
			scrollbar.setHidden(false);
			hiddenByPlugin = false;
		}
	}

	/**
	 * In combat = a hitsplat on the player or their target within the last {@code timeoutTicks}
	 * ticks. A hitsplat tick ahead of the current tick (the tick counter reset, e.g. on relog) is
	 * treated as stale.
	 */
	static boolean isInCombat(int lastHitsplatTick, int currentTick, int timeoutTicks)
	{
		return lastHitsplatTick != NO_HITSPLAT
			&& currentTick >= lastHitsplatTick
			&& currentTick - lastHitsplatTick <= timeoutTicks;
	}

	/**
	 * Converts seconds to game ticks, rounding up so the scrollbar never comes back early.
	 */
	static int secondsToTicks(int seconds)
	{
		return (seconds * 1000 + GAME_TICK_MILLIS - 1) / GAME_TICK_MILLIS;
	}

	@Provides
	ChatScrollbarHiderConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(ChatScrollbarHiderConfig.class);
	}
}

package com.eitjank.chatscrollbarhider;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

public class ChatScrollbarHiderPluginTest
{
	public static void main(String[] args) throws Exception
	{
		ExternalPluginManager.loadBuiltin(ChatScrollbarHiderPlugin.class);
		RuneLite.main(args);
	}
}

package com.eitjank.chatscrollbarhider;

import static com.eitjank.chatscrollbarhider.ChatScrollbarHiderPlugin.NO_HITSPLAT;
import static com.eitjank.chatscrollbarhider.ChatScrollbarHiderPlugin.isInCombat;
import static com.eitjank.chatscrollbarhider.ChatScrollbarHiderPlugin.secondsToTicks;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

public class InCombatTest
{
	private static final int TIMEOUT = 25;

	@Test
	public void noHitsplatIsNotCombat()
	{
		assertFalse(isInCombat(NO_HITSPLAT, 100, TIMEOUT));
	}

	@Test
	public void hitsplatThisTickIsCombat()
	{
		assertTrue(isInCombat(100, 100, TIMEOUT));
	}

	@Test
	public void hitsplatAtTimeoutEdgeIsCombat()
	{
		assertTrue(isInCombat(100, 100 + TIMEOUT, TIMEOUT));
	}

	@Test
	public void hitsplatPastTimeoutIsNotCombat()
	{
		assertFalse(isInCombat(100, 100 + TIMEOUT + 1, TIMEOUT));
	}

	@Test
	public void hitsplatAtTickZeroCounts()
	{
		assertTrue(isInCombat(0, 3, TIMEOUT));
	}

	@Test
	public void hitsplatFromBeforeTickCounterResetIsNotCombat()
	{
		assertFalse(isInCombat(5000, 2, TIMEOUT));
	}

	@Test
	public void secondsToTicksRoundsUp()
	{
		assertEquals(25, secondsToTicks(15));
		assertEquals(5, secondsToTicks(3));
		assertEquals(2, secondsToTicks(1));
		assertEquals(500, secondsToTicks(300));
	}
}
